using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_Response_IsRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(_evaluatorClient)
        };

        var result = await EvaluationExtensions.EvaluateAsync(
            evaluators,
            messages,
            response,
            _evaluatorClient);

        foreach (var metric in result.Metrics)
        {
            Assert.IsTrue(
                metric.Value.Rating >= EvaluationRating.Good,
                $"Metric '{metric.Key}' rated {metric.Value.Rating}: {metric.Value.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsGrounded()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions about geography."),
            new(ChatRole.User, "Name the three largest countries by area.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(_evaluatorClient),
            new CoherenceEvaluator(_evaluatorClient)
        };

        var result = await EvaluationExtensions.EvaluateAsync(
            evaluators,
            messages,
            response,
            _evaluatorClient);

        foreach (var metric in result.Metrics)
        {
            Assert.IsTrue(
                metric.Value.Rating >= EvaluationRating.Good,
                $"Metric '{metric.Key}' rated {metric.Value.Rating}: {metric.Value.Reason}");
        }
    }

    [TestMethod]
    public async Task Chat_Response_IsCoherent()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in two sentences.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(_evaluatorClient)
        };

        var result = await EvaluationExtensions.EvaluateAsync(
            evaluators,
            messages,
            response,
            _evaluatorClient);

        foreach (var metric in result.Metrics)
        {
            Assert.IsTrue(
                metric.Value.Rating >= EvaluationRating.Good,
                $"Metric '{metric.Key}' rated {metric.Value.Rating}: {metric.Value.Reason}");
        }
    }
}

